import React, { useRef } from 'react';
import { CalendarEvent } from '../types';

interface EventCardProps {
  event: CalendarEvent;
  onDragStart: (e: React.DragEvent, id: string) => void;
  onRenderRecord: (id: string) => void;
  onDelete: (id: string) => void;
}

const RawEventCard: React.FC<EventCardProps> = ({
  event,
  onDragStart,
  onRenderRecord,
  onDelete
}) => {
  // Directly track actual render executions without triggering re-render cascades
  const hasMounted = useRef(false);
  if (!hasMounted.current) {
    hasMounted.current = true;
    onRenderRecord(event.id);
  } else {
    onRenderRecord(event.id);
  }

  const categoryClass = event.category.replace(' ', '-');

  return (
    <div
      draggable
      onDragStart={(e) => onDragStart(e, event.id)}
      className={`telemetry-card ${categoryClass}`}
    >
      <div className="card-top">
        <span className="card-time">{event.time}</span>
        <button
          className="card-close"
          onClick={(e) => {
            e.stopPropagation();
            onDelete(event.id);
          }}
          title="Delete event"
        >
          ×
        </button>
      </div>
      <div className="card-name">{event.title}</div>
    </div>
  );
};

export const MemoizedEventCard = React.memo(RawEventCard);
export const UnmemoizedEventCard = RawEventCard;
